#!/usr/bin/env node
// SPDX-License-Identifier: MIT
//
// Fails when the Android release build type would produce a debuggable APK.
//
// WHY this exists: `packages/mobile/src-tauri/gen/android` is generated by Tauri
// but tracked in git. Running `tauri android init` rewrites build.gradle.kts and
// restores upstream's `isDebuggable = true`, so the flag silently returns inside
// whatever commit happened to run the generator. It was fixed by b93da6ab and
// again by 0039b246, and regressed both times — most recently through cf812982,
// a commit about dialog crashes, where nobody would look for it.
//
// A debuggable release APK lets anyone holding the device attach a debugger and
// read application storage. For this app that means the provider credentials the
// agent keeps. It also blocks a Play Store submission outright.

import { readFileSync } from "node:fs"
import { fileURLToPath } from "node:url"
import { dirname, join } from "node:path"

const root = join(dirname(fileURLToPath(import.meta.url)), "..")
const gradlePath = join(root, "packages/mobile/src-tauri/gen/android/app/build.gradle.kts")
const manifestPath = join(root, "packages/mobile/src-tauri/gen/android/app/src/main/AndroidManifest.xml")

const failures = []

let gradle
try {
  gradle = readFileSync(gradlePath, "utf8")
} catch {
  console.error(`Android release flags: cannot read ${gradlePath}`)
  console.error("Run `bun tauri android init` in packages/mobile first.")
  process.exit(1)
}

// Isolate the release block so a legitimate `isDebuggable = true` in the debug
// block is not mistaken for a regression.
const releaseStart = gradle.indexOf('getByName("release")')
if (releaseStart === -1) {
  failures.push('no getByName("release") block found in build.gradle.kts')
} else {
  let depth = 0
  let end = -1
  for (let i = gradle.indexOf("{", releaseStart); i < gradle.length; i++) {
    if (gradle[i] === "{") depth++
    else if (gradle[i] === "}") {
      depth--
      if (depth === 0) {
        end = i
        break
      }
    }
  }
  const block = gradle.slice(releaseStart, end === -1 ? gradle.length : end)
  if (/isDebuggable\s*=\s*true/.test(block)) {
    failures.push("build.gradle.kts: the release build type sets isDebuggable = true")
  }
  if (/isJniDebuggable\s*=\s*true/.test(block)) {
    failures.push("build.gradle.kts: the release build type sets isJniDebuggable = true")
  }
}

try {
  const manifest = readFileSync(manifestPath, "utf8")
  if (/android:debuggable\s*=\s*"true"/.test(manifest)) {
    failures.push('AndroidManifest.xml declares android:debuggable="true"')
  }
} catch {
  // The manifest is generated alongside the gradle file; its absence is already
  // reported by check-android-runtime.mjs, so stay silent rather than duplicate.
}

if (failures.length > 0) {
  console.error("Android release flags: REFUSED")
  for (const failure of failures) console.error(`  - ${failure}`)
  console.error("")
  console.error("A debuggable release exposes app storage — provider tokens included.")
  console.error("If `tauri android init` just regenerated gen/android, re-apply the flag.")
  process.exit(1)
}

console.log("Android release flags OK: release build type is not debuggable")
